/**
 * Property-based tests for NetworkComponent security rules.
 *
 * **Validates: Requirement 1.8**
 *
 * Property 1: No Public Postgres Port
 * For any configuration of admin CIDRs, the Security List ingress rules
 * generated by buildIngressRules() must never permit TCP port 5432 from
 * any source. Postgres is only reachable within the Docker bridge network
 * (auth-net) on the VM itself — never from the public internet.
 */

import * as fc from "fast-check";
import { describe, expect, it } from "vitest";
import { buildIngressRules, type IngressRule } from "../network.js";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Returns true if the given ingress rule permits TCP traffic on port 5432.
 * A rule "permits" port 5432 when:
 *   - protocol is "6" (TCP), AND
 *   - tcpOptions.min <= 5432 <= tcpOptions.max
 *     (covers both exact-port rules and port-range rules)
 */
function rulePermitsTcp5432(rule: IngressRule): boolean {
  if (rule.protocol !== "6") return false;
  if (!rule.tcpOptions) return false;
  return rule.tcpOptions.min <= 5432 && rule.tcpOptions.max >= 5432;
}

// ---------------------------------------------------------------------------
// Arbitrary generators
// ---------------------------------------------------------------------------

/**
 * Generates a single CIDR string in the form "A.B.C.D/prefix".
 * Covers the realistic range of admin CIDR inputs an operator might supply.
 */
const cidrArb = fc
  .tuple(
    fc.integer({
      min: 0,
      max: 255,
    }),
    fc.integer({
      min: 0,
      max: 255,
    }),
    fc.integer({
      min: 0,
      max: 255,
    }),
    fc.integer({
      min: 0,
      max: 255,
    }),
    fc.integer({
      min: 0,
      max: 32,
    }),
  )
  .map(([a, b, c, d, prefix]) => `${a}.${b}.${c}.${d}/${prefix}`);

/**
 * Generates an array of 0–10 CIDR strings (including the empty-array case
 * which exercises the default-CIDR fallback path).
 */
const adminCidrsArb = fc.array(cidrArb, {
  minLength: 0,
  maxLength: 10,
});

// ---------------------------------------------------------------------------
// Property 1: No Public Postgres Port
// ---------------------------------------------------------------------------

describe("Property 1: No Public Postgres Port", () => {
  /**
   * **Validates: Requirement 1.8**
   *
   * For any array of admin CIDRs (including empty arrays, single CIDRs,
   * and up to 10 CIDRs), buildIngressRules() must never produce a rule
   * that permits TCP port 5432 from any source.
   */
  it("never permits TCP 5432 for any admin CIDR configuration", () => {
    fc.assert(
      fc.property(adminCidrsArb, (adminCidrs) => {
        const rules = buildIngressRules(adminCidrs);

        const postgres5432Rules = rules.filter(rulePermitsTcp5432);

        expect(postgres5432Rules).toHaveLength(0);
      }),
      {
        numRuns: 1000,
      },
    );
  });

  it("never permits TCP 5432 when adminCidrs is empty", () => {
    const rules = buildIngressRules([]);
    const postgres5432Rules = rules.filter(rulePermitsTcp5432);
    expect(postgres5432Rules).toHaveLength(0);
  });

  it("never permits TCP 5432 when adminCidrs contains 0.0.0.0/0 (open SSH)", () => {
    const rules = buildIngressRules(["0.0.0.0/0"]);
    const postgres5432Rules = rules.filter(rulePermitsTcp5432);
    expect(postgres5432Rules).toHaveLength(0);
  });

  it("never permits TCP 5432 with multiple admin CIDRs", () => {
    const rules = buildIngressRules(["203.0.113.0/24", "198.51.100.0/24", "192.0.2.1/32"]);
    const postgres5432Rules = rules.filter(rulePermitsTcp5432);
    expect(postgres5432Rules).toHaveLength(0);
  });

  it("only permits the expected ports (443, 80, 22) for TCP protocol", () => {
    fc.assert(
      fc.property(adminCidrsArb, (adminCidrs) => {
        const rules = buildIngressRules(adminCidrs);

        const tcpRules = rules.filter((r) => r.protocol === "6");

        for (const rule of tcpRules) {
          expect(rule.tcpOptions).toBeDefined();
          const { min, max } = rule.tcpOptions!;
          // Each TCP rule must be for exactly one of: 443, 80, or 22
          const isAllowedPort =
            (min === 443 && max === 443) ||
            (min === 80 && max === 80) ||
            (min === 22 && max === 22);
          expect(isAllowedPort).toBe(true);
        }
      }),
      {
        numRuns: 500,
      },
    );
  });
});
